def select(id,pt,en,items):return label(id,pt,en,f'<select id="{id}">'+''.join(option(v,a,b) for v,a,b in items)+'</select>')
def controls(p):
    kind=p['kind']
    if kind=='twin':return select('frontier-policy','Modelo de previsão','Forecast model',[('ridge','Ridge calibrado','Calibrated ridge'),('persistence','Persistência','Persistence')])+select('frontier-capacity','Capacidade por trecho (veículos/h)','Capacity per link (vehicles/h)',[(str(c),str(c),str(c)) for c in (2400,3200,4000)])
    cities=[('balanced','Balanceada','Balanced'),('commuter','Pendular','Commuter'),('storm','Tempestade / falha','Storm / outage')] if kind=='energy' else [('grid','Grade urbana','Urban grid'),('river','Rio e pontes','River and bridges'),('ladder','Corredor em escada','Ladder corridor')]
    policies=[('nearest','Carregador mais próximo','Nearest charger'),('reservation','Recarga coordenada','Coordinated charging'),('bandit','Bandit contextual','Contextual bandit')] if kind=='energy' else [('nearest','Leilão espera/distância','Wait-distance auction'),('equity','Prioridade geográfica','Geographic priority'),('robust','Resiliência + demanda','Resilience + demand')]
    result=select('frontier-city','Cenário urbano','Urban scenario',cities)+select('frontier-fleet','Tamanho da frota','Fleet size',[(str(n),str(n),str(n)) for n in ((12,24) if kind=='energy' else (8,16))])+select('frontier-policy','Estratégia','Strategy',policies)
    if kind=='civic':result+=select('frontier-event','Evento','Event',[('reference','Referência','Reference'),('stress','Estresse descoberto','Discovered stress')])
    return result

def page(p,report):
    kind=p['kind'];slug=p['slug'];synthetic=kind!='twin'
    evidence=[('2.016','contagens reais','real counts'),('403','observações de teste','test observations'),('90%','alvo de cobertura, não garantia','coverage target, not guarantee')] if kind=='twin' else [('18','configurações','configurations'),('54','execuções de teste','test runs'),('3','estratégias de recarga','charging strategies')] if kind=='energy' else [('36','configurações','configurations'),('144','execuções de teste','test runs'),('3','topologias urbanas','urban topologies')]
    summary=''.join('<div class="summary-item">'+bi('h3',a,b)+bi('p',*p[key])+'</div>' for key,a,b in [('innovation','Hipótese de inovação','Innovation hypothesis'),('works','Implementação atual','Current implementation'),('validation','Experimentos e validação','Experiments and validation'),('limits','Limites e resultados negativos','Limitations and negative results')])
    if kind=='twin':
        ridge=next(m for m in report['models'] if m['model']=='ridge');baseline=next(m for m in report['models'] if m['model']=='persistence');result=(f"No teste cronológico: RMSE ridge {ridge['metrics']['rmse']:.1f} versus persistência {baseline['metrics']['rmse']:.1f} veículos/h. A cobertura ridge foi {100*ridge['metrics']['coverage']:.1f}%, abaixo do alvo de 90%. Ganho pontual não estabelece generalização para outras cidades.",f"Chronological test: ridge RMSE {ridge['metrics']['rmse']:.1f} versus persistence {baseline['metrics']['rmse']:.1f} vehicles/h. Ridge coverage was {100*ridge['metrics']['coverage']:.1f}%, below the 90% target. A single result does not establish transfer to other cities.")
    else:result=('Os resultados incluem políticas que perdem para referências simples. Explore o mesmo cenário e leia métricas individuais antes de concluir que aprendizado ou coordenação sempre ajudam.','Results include policies that lose to simple baselines. Explore the same scenario and read individual metrics before concluding that learning or coordination always help.')
    provenance=('Protótipo de pesquisa independente. Contagens reais atribuídas; movimentos e intervenções sintéticos. Não é um gêmeo operacional certificado.','Independent research prototype. Attributed real counts; synthetic movement and interventions. Not a certified operational twin.') if not synthetic else ('Protótipo de pesquisa independente com dados sintéticos. Inovação é uma hipótese investigada, não superioridade ou revolução comprovada.','Independent research prototype using synthetic data. Innovation is an investigated hypothesis, not proven superiority or a proven revolution.')
    assets=bi('a','Dados observados CSV','Observed data CSV','class="button ghost" href="source/observed.csv" download')+bi('a','Proveniência e licença','Provenance and license','class="button ghost" href="source/DATA_SOURCE.json"') if kind=='twin' else bi('a','Dataset sintético CSV','Synthetic dataset CSV','class="button ghost" href="source/demand-sample.csv" download')
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(p['description'])}"><title>{esc(p['title'])} · Murillo Carvalho</title><link rel="stylesheet" href="../../styles.css"><link rel="stylesheet" href="../../projects.css"><link rel="stylesheet" href="../mobility.css"><script src="../../script.js" defer></script><script type="module" src="../frontier-lab.js"></script></head><body class="project-detail mobility-page" data-frontier="{kind}"><a class="skip-link" href="#content">Ir ao conteúdo / Skip to content</a><header class="topbar"><a class="logo" href="../../#home">Murillo<span>Ed</span></a><nav><a href="../temas/{TOPIC}/">ML e AI Mobility</a></nav><div class="header-tools"><button class="lang-toggle" type="button">EN / PT</button></div></header><main id="content" class="shell"><section class="project-detail-hero"><div><span class="section-index">MOBILITY FRONTIERS / RESEARCH PROTOTYPE</span>{bi('h1',p['title'],p['title_en'])}{bi('p',p['description'],p['description_en'],'class="project-lead"')}<div class="project-tags">{''.join('<span>'+esc(t)+'</span>' for t in p['tags'])}</div><div class="hero-actions">{bi('a','Baixar código Python','Download Python source','class="button primary" href="source.zip" download')}{bi('a','Relatório de execução','Experiment report','class="button ghost" href="report.json"')}{bi('a','Ver código no GitHub','View source on GitHub',f'class="button ghost" href="https://github.com/murilloed/murilloed.github.io/tree/main/projects/{slug}/source" target="_blank" rel="noreferrer"')}</div></div><img class="detail-cover" src="../../assets/projects/{slug}.svg" alt="{esc(p['title'])}" width="640" height="360"></section><div class="project-evidence">{''.join('<div><strong>'+a+'</strong>'+bi('span',b,c)+'</div>' for a,b,c in evidence)}</div>{bi('p',*provenance,'class="project-provenance"')}<section class="project-panel project-summary">{bi('h2','Pesquisa que pode evoluir para produto','Research that can evolve into a product')}<div class="summary-grid">{summary}</div></section><section class="project-panel mobility-lab">{bi('span','LABORATÓRIO / EXECUÇÕES PYTHON','LAB / PYTHON RUNS','class="mini-label"')}{bi('h2','Experimente as decisões','Explore the decisions')}{bi('p','Selecione uma configuração e execute para carregar o resultado Python correspondente. A reprodução mostra a evolução temporal; não executa Python no navegador.','Choose a configuration and run to load the matching Python result. Playback shows temporal evolution; Python does not execute in the browser.')}<div class="mobility-controls">{controls(p)}{bi('button','Executar cenário','Run scenario','id="frontier-run" type="button"')}</div><div class="mobility-stage"><svg id="frontier-map" viewBox="0 0 640 490" role="img" aria-label="Mobility research simulation"></svg><div><div class="mobility-stats" id="frontier-stats"></div><p id="frontier-status" aria-live="polite">Loading…</p></div></div><div class="mobility-controls">{bi('button','Reproduzir','Play','id="frontier-play" type="button"')}{bi('button','Exportar cenário JSON','Export scenario JSON','id="frontier-export" type="button"')}</div>{label('frontier-timeline','Instante da reprodução','Playback time','<input class="mobility-progress" id="frontier-timeline" type="range" min="0" max="99" value="0">')}</section><section class="project-panel">{bi('h2','Compare referências e propostas','Compare baselines and proposals')}<div class="mobility-experiments" id="frontier-comparison"></div>{bi('p',*result,'class="mobility-note"')}</section><section class="project-panel">{bi('h2','Dados, hipóteses e procedência','Data, assumptions and provenance')}{bi('p',*p['data'])}<div class="hero-actions">{assets}</div>{''.join(f'<p><a href="{esc(url)}" target="_blank" rel="noreferrer">{esc(title)}</a></p>' for title,url in p['refs'])}</section><div class="project-detail-grid"><section class="project-panel">{bi('h2','Reproduza ou modifique','Reproduce or modify')}{bi('p','Extraia o ZIP e use Python 3.10 ou superior. Sem dependências externas. O README documenta parâmetros, seeds, unidades e limites.','Extract the ZIP and use Python 3.10 or later. No external dependencies. README documents parameters, seeds, units and limitations.')}<pre><code>python {p['package']}.py --output report.json\npython -m unittest discover -v</code></pre></section><section class="project-panel">{bi('h2','O próximo avanço a demonstrar','The next advance to demonstrate')}{bi('p',*p['next'])}</section></div><section class="project-panel result-panel">{bi('h2','Inspecione a evidência','Inspect the evidence')}<details>{bi('summary','Parâmetros, resultados individuais e limitações','Parameters, individual results and limitations')}<pre><code id="frontier-report">Loading…</code></pre></details></section><a href="../temas/{TOPIC}/" class="button ghost back-projects">ML e AI Mobility</a></main><footer class="site-footer">© <span id="year"></span> Murillo Carvalho</footer></body></html>'''

def card(p):
    if p.get('kind') not in ('twin','energy','civic'):return old_card(p)
    status=('Dados reais + simulação','Real data + simulation') if p['kind']=='twin' else ('Protótipo de pesquisa · sintético','Research prototype · synthetic')
    slug=p['slug'];description=bi('p',p['description'],p['description_en'],'class="project-description"')
    explore=bi('a','Explorar projeto','Explore project',f'href="../../{slug}/"')
    download=bi('a','Baixar código','Download source',f'href="../../{slug}/source.zip" download')
    tags=''.join('<span>'+esc(t)+'</span>' for t in p['tags'])
    return f'''<article class="project-card" data-category="{p['category']}"><a class="project-cover" href="../../{slug}/" aria-label="{esc(p['title'])}"><img src="../../../assets/projects/{slug}.svg" width="640" height="360" alt="" loading="lazy"></a><div class="project-body"><div class="project-status">{bi('span',*status)}</div>{bi('h3',p['title'],p['title_en'])}{description}<div class="project-tags">{tags}</div><div class="project-actions">{explore}{download}</div></div></article>'''

def cover(p):
    art='';kind=p['kind']
    if kind=='twin':
        art='<path d="M50 230 H590 M50 80 V230" stroke="#456175"/>'
        points=[(60+i*24,160+45*__import__('math').sin(i*.55)) for i in range(22)]
        art+='<polyline points="'+' '.join(f'{x},{y:.1f}' for x,y in points)+'" fill="none" stroke="#2de2e6" stroke-width="5"/>'
        art+='<polyline points="'+' '.join(f'{x},{y+12*__import__("math").cos(i):.1f}' for i,(x,y) in enumerate(points))+'" fill="none" stroke="#eaba73" stroke-width="3"/>'
    else:
        for y in range(4):
            for x in range(4):
                px,py=160+x*105,60+y*55;art+=f'<circle cx="{px}" cy="{py}" r="7" fill="#2de2e6"/>'
                if x<3:art+=f'<path d="M{px+9} {py} h87" stroke="#42677b" stroke-width="3"/>'
                if y<3:art+=f'<path d="M{px} {py+9} v37" stroke="#42677b" stroke-width="3"/>'
        if kind=='energy':art+='<path d="M315 80 l-30 70 h35 l-10 50 60-85 h-40 l20-35" fill="#a5df80"/>'
        else:art+='<circle cx="370" cy="170" r="45" fill="none" stroke="#edb568" stroke-dasharray="7 6" stroke-width="4"/><path d="M263 90 l30 35 m0-35 l-30 35" stroke="#ff8588" stroke-width="6"/>'
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360" viewBox="0 0 640 360"><rect width="640" height="360" fill="#081b2c"/><text x="30" y="30" fill="#69c5c8" font-family="monospace" font-size="13">MOBILITY FRONTIERS / RESEARCH</text>{art}<text x="30" y="315" fill="#e7f2ff" font-family="system-ui" font-size="21">{esc(p["title"])}</text></svg>'

def build():
    catalog=json.loads((ROOT/'projects.json').read_text(encoding='utf-8'))
    license_text=(ROOT/'projects/gps-routelab/source/LICENSE').read_text(encoding='utf-8')
    for p in NEW:
        folder=ROOT/'projects'/p['slug'];report=json.loads((folder/'report.json').read_text(encoding='utf-8'))
        if p['kind']!='twin':
            spec=importlib.util.spec_from_file_location(p['package'],folder/'source'/f'{p["package"]}.py');module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
            rows=module.demand('balanced',7) if p['kind']=='energy' else module.demand('river',7,{'hotspot':15,'edge':0,'surge':5})
            with (folder/'source/demand-sample.csv').open('w',newline='',encoding='utf-8') as handle:
                writer=csv.DictWriter(handle,fieldnames=['id','minute','origin','destination']);writer.writeheader();writer.writerows(rows)
        (folder/'index.html').write_text(page(p,report),encoding='utf-8');(ROOT/'assets/projects'/f'{p["slug"]}.svg').write_text(cover(p),encoding='utf-8')
        readme=f'# {p["title_en"]}\n\n{p["description_en"]}\n\n## Research hypothesis\n\n{p["innovation"][1]}\n\n## Run\n\nPython 3.10+, standard library only. From this directory:\n\n```sh\npython {p["package"]}.py --output report.json\npython -m unittest discover -v\n```\n\n## Implementation\n\n{p["works"][1]}\n\n## Validation protocol\n\n{p["validation"][1]}\n\n## Data and units\n\n{p["data"][1]}\n\n## Limitations\n\n{p["limits"][1]}\n\n## Next research step\n\n{p["next"][1]}\n\nNo client endorsement or production performance claim. Consult the generated report for all model parameters, individual metrics and negative results. Browser demonstrations replay generated Python output.\n'
        if p['kind']=='twin':readme+='\n## Data attribution and custom CSV\n\nCode is MIT; `observed.csv` is adapted from Hogue (2019), UCI Metro Interstate Traffic Volume, DOI 10.24432/C5X60B, CC BY 4.0: https://creativecommons.org/licenses/by/4.0/ . See DATA_SOURCE.json for sample transformations, upstream SHA256 and timestamp semantics. No endorsement by the data creator or MnDOT is implied.\n\n`python fetch_data.py` rebuilds the attributed sample from the official UCI ZIP (network required only for this refresh). The archive already includes observed.csv for offline reproduction.\n\n`python twinpulse.py --observed your.csv --output custom-report.json` accepts strictly increasing unique ISO timestamps and finite nonnegative volume counts (columns timestamp,volume; minimum 100 rows). Only adjacent observations exactly one hour apart form prediction pairs. This CLI evaluates counts; it does not prove causal validity of road-capacity changes. At least one hour of observed history is required per forecast. Temporal dependence/drift can reduce interval coverage below the nominal 90%.\n'
        else:readme+=f'\n## Custom scenario\n\n`python {p["package"]}.py --single --city {"storm" if p["kind"]=="energy" else "river"} --fleet 12 --policy {"reservation" if p["kind"]=="energy" else "robust"} --seed 42 --export-demand demand.csv --output custom-run.json`\n\n`demand-sample.csv` contains generated requests (seed 7; {"balanced EV scenario" if p["kind"]=="energy" else "river scenario with hotspot 15, edge 0 and surge 5"}). Columns: id,minute,origin,destination; zones 0..15. All requests in this sample are synthetic.\n\nPolicy definitions and experiment seeds are recorded in report.json. Imported real-world measurements are not included in this project. Calibrate and externally validate assumptions before applying results to a real fleet.\n'
        (folder/'source/README.md').write_text(readme,encoding='utf-8');(folder/'source/LICENSE').write_text(license_text,encoding='utf-8')
        with zipfile.ZipFile(folder/'source.zip','w',zipfile.ZIP_DEFLATED) as archive:
            for file in sorted((folder/'source').iterdir()):
                if file.is_file():archive.write(file,file.name)
        entry={k:p[k] for k in ('slug','title','title_en','category','context','description','description_en','tags','package','themes')}
        if not any(x['slug']==p['slug'] for x in catalog):catalog.append(entry)
    (ROOT/'projects.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    topic=ROOT/'projects/temas'/TOPIC/'index.html';markup=topic.read_text(encoding='utf-8')
    markup=re.sub(r'<div class="projects-grid">.*?</main>',f'<div class="projects-grid">{"".join(card(p) for p in NEW+ORIGINAL)}</div></main>',markup,flags=re.S)
    markup=re.sub(r'<p class="projects-count".*?</p>',bi('p','6 projetos','6 projects','class="projects-count"'),markup)
    markup=markup.replace('Três laboratórios reproduzíveis de mobilidade urbana: rotas GPS, dinâmica de carros e decisões inteligentes de frotas. Python, experimentação e demonstrações interativas.','Seis laboratórios de mobilidade: rotas, tráfego, frotas, dados reais, energia e resiliência. Python, aprendizado e experimentação reproduzível.').replace('Three reproducible urban mobility labs: GPS routing, car dynamics and intelligent fleet decisions. Python, experimentation and interactive demos.','Six mobility labs: routing, traffic, fleets, real data, energy and resilience. Python, learning and reproducible experimentation.')
    markup=markup.replace('Independent research · Synthetic data · No real-world performance claim','Independent research · Attributed real counts in TwinPulse; synthetic scenarios elsewhere · No production performance claim')
    topic.write_text(markup,encoding='utf-8')
    allpath=ROOT/'projects/temas/todos/index.html';markup=allpath.read_text(encoding='utf-8')
    for p in NEW:
        if f'href="../../{p["slug"]}/"' not in markup:markup=markup.replace('</div></main>',card(p)+'</div></main>')
    markup=re.sub(r'data-pt="\d+ projetos" data-en="\d+ projects">\d+ projetos',f'data-pt="{len(catalog)} projetos" data-en="{len(catalog)} projects">{len(catalog)} projetos',markup);allpath.write_text(markup,encoding='utf-8')
    index=ROOT/'index.html';markup=index.read_text(encoding='utf-8')
    markup=markup.replace('Simulação urbana, rotas GPS, carros e IA para frotas.','Rotas, frotas, energia, resiliência e validação com dados reais.').replace('Urban simulation, GPS routing, cars and fleet AI.','Routing, fleets, energy, resilience and real-data validation.')
    markup=re.sub(r'(<a class="project-topic" href="projects/temas/ml-ai-mobility/">.*?<span) data-pt="\d+ projetos" data-en="\d+ projects">\d+ projetos',r'\1 data-pt="6 projetos" data-en="6 projects">6 projetos',markup,flags=re.S)
    markup=markup.replace('21 projetos →',f'{len(catalog)} projetos →').replace('21 projects →',f'{len(catalog)} projects →');index.write_text(markup,encoding='utf-8')
    print(f'Built 3 frontier projects; {len(catalog)} total projects; 6 mobility labs.')
if __name__=='__main__':build()
